    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Diario Official do Estado de São Paulo - 1 de Abril de 1910</title>
    <style>
        @page {
            size: A4;
            margin: 1.5cm 1cm;
        }

        body {
            font-family: "Times New Roman", Times, "Liberation Serif", serif;
            color: #000;
            background-color: #fff;
            margin: 0 auto;
            padding: 20px;
            max-width: 900px;
            line-height: 1.25;
            font-size: 13.5px;
        }

        /* Cabeçalho Principal */
        .header {
            text-align: center;
            margin-bottom: 8px;
        }

        .header .country {
            font-size: 19px;
            font-weight: 900;
            letter-spacing: 2px;
            margin: 0;
            text-transform: uppercase;
        }

        .header .title {
            font-size: 54px;
            font-weight: 900;
            letter-spacing: -0.5px;
            margin: 0;
            line-height: 1;
            text-transform: uppercase;
            font-stretch: expanded;
        }

        .header .subtitle {
            font-size: 20px;
            font-weight: bold;
            letter-spacing: 2.5px;
            margin-top: 4px;
            margin-bottom: 8px;
            text-transform: uppercase;
        }

        /* Barra de Informações / Metadados */
        .info-bar {
            border-top: 2px solid #000;
            border-bottom: 2px solid #000;
            padding: 3px 0;
            margin-bottom: 12px;
            position: relative;
        }

        .info-bar-inner {
            border-top: 1px solid #000;
            border-bottom: 1px solid #000;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 3px 5px;
            font-size: 11.5px;
            font-weight: bold;
            text-transform: uppercase;
        }

        /* Estrutura de Colunas */
        .container {
            display: flex;
            gap: 16px;
        }

        .column {
            flex: 1;
            text-align: justify;
        }

        .column-left {
            padding-right: 12px;
            border-right: 1px solid #000;
        }

        .column-right {
            padding-left: 4px;
        }

        /* Tipografia e Elementos do Texto */
        h2.section-title {
            text-align: center;
            font-size: 26px;
            font-family: "Old English Text MT", "Engravers Old English", "UnifrakturCook", Georgia, serif;
            font-weight: normal;
            margin: 0 0 10px 0;
        }

